window.products.push({"id":972256,"name":"Gone Home Garnish Picks with Speckled Multicolor Beads, Set of 10","category":"homeandappliances","retail price":18.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/61ZEa9VnxBL._AC_SL1500_.jpg","description":"Marion Chubon has made an art form out of twisted metal and beads. Her stylish garnish picks use nickel wire which she skillfully twists into amazingly consistent swirls and spirals and then accents with colorful beads. They're ideal for cocktails, and hors d'oeuvres, or get creative and stick them in a hunk of cheese with a card attached identifying the variety. The possibilities are limited only by your imagination.","images":["https://m.media-amazon.com/images/I/61ZEa9VnxBL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Gone Home","source_asin":"B01N36I0ZR","category_path":"Home & Kitchen"},"sku":"BM-972256","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01N36I0ZR","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01N36I0ZR","price_pending":true,"merchant_ready":false});
window.products.push({"id":972257,"name":"Living Quarters Queen Electric Blanket, Khaki Stone","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61oYQDZn87L._AC_SL1200_.jpg","description":"Lower your heating bill and save energy this winter with a cozy, heated microlight blanket which features an ultra-thin wire for extra comfort. Made from ultra-soft microplush fabric. The blanket is controlled by a programmable digital controller; 2 are included with queen and king sized blankets. The controller includes 10 heat settings, a preheat setting, and a 10 hour auto shut off feature, allowing you save up to 10 percent a year on your energy bill. Just turn on your heated blanket and your thermostat down by 10-15 percent for 8 hours to realize the savings. Incredibly convenient, the electric blanket is machine washable.","images":["https://m.media-amazon.com/images/I/61oYQDZn87L._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Living Quarters","source_asin":"B084MNQ7CN","category_path":"Home & Kitchen"},"sku":"BM-972257","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B084MNQ7CN","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B084MNQ7CN","price_pending":true,"merchant_ready":false});
