window.products.push({"id":972645,"name":"VIOK 2 in 1 Bag Sealer with Cutter, Heat Sealer Mini Bag Sealer, Handheld Heat Sealer with Lanyard Sealing Machine For Kitchen","category":"homeandappliances","retail price":12.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/61dO5xPFJiL._AC_SL1500_.jpg","description":"Quick & Easy Way to Reseal Bags：Use the chip heat sealer machine on chip/snack bags when you can’t finish them or if you are planning on only eating part of the food. Come aim handy after the kids open a snack and don’t want to finish it off. Simply seal it for later, and also has a cutter to open them.","images":["https://m.media-amazon.com/images/I/61dO5xPFJiL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"VIOK","source_asin":"B0BX92F5JJ","category_path":"Home & Kitchen"},"sku":"BM-972645","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0BX92F5JJ","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0BX92F5JJ","price_pending":true,"merchant_ready":false});
